import {canvas,renderDocument,maskCanvas} from './renderer.js';
import {createLayer} from './model.js';
import {createPhotoWorker} from './photo-client.js';
import {polygon} from './face-geometry.js';
import {analyzeSkinSurface} from './skin-surface.js';
import {affineFromPairs,referencePatch,guidedColor,featherMask} from './restoration-math.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const FEATURES={dark:['Đốm tối tương đối','Vùng tối hơn nền da cục bộ'],red:['Đỏ tương đối','Vùng lệch đỏ so với lân cận'],bright:['Đốm sáng / kết cấu sáng','Vùng sáng và ít bão hòa tương đối'],creases:['Rãnh tối dài','Ứng viên rãnh hoặc nếp nhìn thấy']};
function maskImage(values,w,h){const c=canvas(w,h),x=c.getContext('2d'),im=x.createImageData(w,h);for(let i=0;i<values.length;i++){im.data[i*4]=im.data[i*4+1]=im.data[i*4+2]=255;im.data[i*4+3]=Math.max(0,Math.min(255,values[i]*255));}x.putImageData(im,0,0);return c;}
function readMask(c){const a=c.getContext('2d').getImageData(0,0,c.width,c.height).data;return Float32Array.from({length:c.width*c.height},(_,i)=>a[i*4+3]/255);}
function fit(target,source){const s=Math.min(1,1100/Math.max(source.width,source.height));target.width=Math.max(1,Math.round(source.width*s));target.height=Math.max(1,Math.round(source.height*s));target.getContext('2d').drawImage(source,0,0,target.width,target.height);}
export function createPrecisionStudio(api,{analyzerFactory=()=>createPhotoWorker('analyze')}={}){
 let active=null;function cancel(){active?.();active=null;}
 function openSkin(){
  cancel();const doc=api.doc(),signature=JSON.stringify(doc),source=renderDocument(doc,api.assets,{scale:Math.min(1,1024/Math.max(doc.width,doc.height))}),w=source.width,h=source.height,raw=source.getContext('2d').getImageData(0,0,w,h).data,analyzer=analyzerFactory();let mounted=true,busy=false,skin=null,analysis=null,key='dark';active=()=>{mounted=false;analyzer.stop();};
  const note=s=>{if(mounted)$('#skin-map-status').textContent=s;};
  function refresh(){if(!mounted)return;const c=$('#skin-map-preview');fit(c,source);const map=analysis?.maps[key];if(map){const overlay=maskImage(map.mask,w,h),x=overlay.getContext('2d');x.globalCompositeOperation='source-in';x.fillStyle='rgba(255,181,123,.72)';x.fillRect(0,0,w,h);c.getContext('2d').drawImage(overlay,0,0,c.width,c.height);}$('#skin-map-results').innerHTML=Object.entries(FEATURES).map(([id,[title,description]])=>`<button class="surface-feature ${id===key?'active':''}" data-surface="${id}" ${!analysis?.maps[id]?'disabled':''}><span><strong>${title}</strong><small>${description}</small></span><b>${analysis?.maps[id]?.count??'—'}</b></button>`).join('');for(const b of document.querySelectorAll('[data-surface]'))b.onclick=()=>{key=b.dataset.surface;refresh();};const selected=analysis?.maps[key];$('#skin-map-summary').textContent=selected?`${selected.count} vùng ứng viên · ${selected.pixels.toLocaleString('vi-VN')} pixel · ${(100*selected.pixels/Math.max(1,analysis.skinPixels)).toFixed(1)}% vùng da. Đây không phải xác suất bệnh.`:'Chưa có bản đồ dấu vết.';$('[data-modal-button="1"]').disabled=!selected?.pixels||busy;}
  function calculate(){if(!skin)return;analysis=analyzeSkinSurface({data:raw,width:w,height:h,skin,sensitivity:Number($('#skin-map-sensitivity').value)/100});note(analysis.status==='ready'?'Đã tách vùng ứng viên. Chọn nhóm để xem và đặt vùng chọn.':analysis.issues.join(' '));refresh();}
  async function detect(){if(busy)return;busy=true;$('#skin-map-analyze').disabled=true;try{note('Đang nhận diện vùng da trên thiết bị…');const data=await analyzer.run(await createImageBitmap(source),note);if(!mounted)return;if(!data.skin)throw Error('Chưa nhận diện được da.');const sm=data.skin;skin=new Float32Array(w*h);for(let y=0;y<h;y++)for(let x=0;x<w;x++)skin[y*w+x]=sm.values[Math.min(sm.height-1,Math.floor((y+.5)*sm.height/h))*sm.width+Math.min(sm.width-1,Math.floor((x+.5)*sm.width/w))];const protect=canvas(w,h),px=protect.getContext('2d');px.fillStyle=px.strokeStyle='#fff';px.lineWidth=Math.max(3,w*.005);for(const face of data.faces||[])for(const region of['lips','leftEye','rightEye','leftBrow','rightBrow']){const p=polygon(face,region,w,h);px.beginPath();p.forEach((v,i)=>i?px.lineTo(v.x,v.y):px.moveTo(v.x,v.y));px.closePath();px.fill();px.stroke();}const a=px.getImageData(0,0,w,h).data;for(let i=0;i<skin.length;i++)if(a[i*4+3])skin[i]=0;calculate();}catch(e){if(mounted&&e.name!=='AbortError')note(e.message);}finally{busy=false;if(mounted){$('#skin-map-analyze').disabled=false;refresh();}}}
  function select(){const map=analysis?.maps[key];if(!map?.pixels)return;if(JSON.stringify(api.doc())!==signature){note('Tài liệu đã đổi. Mở lại để phân tích đúng ảnh.');return;}const c=canvas(doc.width,doc.height);c.getContext('2d').drawImage(maskImage(map.mask,w,h),0,0,doc.width,doc.height);const uri=c.toDataURL();api.assets.set(uri,c);doc.selection={type:'paint',source:uri,x:0,y:0,width:doc.width,height:doc.height,feather:0,invert:false};mounted=false;analyzer.stop();api.closeModal();api.commit('Chọn vùng '+FEATURES[key][0]);api.toast('Đã đặt vùng chọn. Tinh chỉnh vùng trên canvas hoặc mở Retouch Lab.');}
  api.showModal('Bản đồ bề mặt da','Nhận diện da · tách dấu vết · duyệt trước khi chỉnh',`<div class="precision-layout"><div><div class="gen-preview-wrap"><canvas id="skin-map-preview" aria-label="Vùng ứng viên retouch trên da"></canvas></div><p id="skin-map-status" class="advanced-status" role="status">Bấm Phân tích để nhận diện da. Xử lý trên thiết bị.</p><p id="skin-map-summary" class="gen-size-note"></p></div><div class="precision-controls"><span class="live-pill">SURFACE MAP</span><h3>Chọn đúng vùng cần sửa.</h3><p class="lab-explanation">AI tách da, loại mắt, môi và chân mày. Phân tích màu và tương phản cục bộ tìm ứng viên dưới đây; ánh sáng, trang điểm và bóng đổ vẫn có thể gây nhầm.</p><button class="button primary" id="skin-map-analyze">Phân tích vùng da</button><label class="lab-slider">Độ nhạy<output id="skin-map-level">100%</output><input type="range" id="skin-map-sensitivity" min="20" max="180" value="100" aria-label="Độ nhạy dấu vết da"></label><div id="skin-map-results"></div><p class="precision-note">Retouch ngoại quan; không kết luận mụn, vảy nến, ung thư da hoặc bệnh khác từ các vùng này. Không tự xóa đốm theo tên bệnh.</p></div></div>`,[{label:'Đóng',run:()=>api.closeModal(true)},{label:'Đặt làm vùng chọn',primary:true,run:select}],()=>{refresh();$('#skin-map-analyze').onclick=detect;$('#skin-map-sensitivity').oninput=e=>{$('#skin-map-level').textContent=e.target.value+'%';calculate();};},()=>{mounted=false;analyzer.stop();});
 }
 function openReference(initial='reference'){
  cancel();const doc=api.doc(),signature=JSON.stringify(doc),scale=1,source=renderDocument(doc,api.assets,{scale}),w=source.width,h=source.height,raw=source.getContext('2d').getImageData(0,0,w,h).data,mask=canvas(w,h),mx=mask.getContext('2d');if(doc.selection)mx.drawImage(maskCanvas(doc,doc.selection,scale,api.assets),0,0,w,h);
  let mounted=true,mode=initial,reference=null,referenceName='',from=[],to=[],picking=false,drawing=null,result=null,record=null,brush='add',brushSize=.035,split=50;const undo=[];active=()=>mounted=false;const note=s=>{if(mounted)$('#reference-status').textContent=s;};
  function marks(c,p,sw,sh){const x=c.getContext('2d');p.forEach((v,i)=>{const px=v.x/sw*c.width,py=v.y/sh*c.height;x.fillStyle='#e5b77b';x.strokeStyle='#142621';x.lineWidth=2;x.beginPath();x.arc(px,py,10,0,Math.PI*2);x.fill();x.stroke();x.fillStyle='#142621';x.font='bold 12px Arial';x.textAlign='center';x.textBaseline='middle';x.fillText(String(i+1),px,py);});}
  function draw(){if(!mounted)return;const c=$('#reference-target');if(!c)return;fit(c,source);const x=c.getContext('2d');if(result){const out=canvas(w,h),ox=out.getContext('2d'),im=ox.createImageData(w,h);im.data.set(result);ox.putImageData(im,0,0);x.save();x.beginPath();x.rect(c.width*split/100,0,c.width,c.height);x.clip();x.drawImage(out,0,0,c.width,c.height);x.restore();}else{const overlay=canvas(w,h),ox=overlay.getContext('2d');ox.drawImage(mask,0,0);ox.globalCompositeOperation='source-in';ox.fillStyle='rgba(157,223,201,.5)';ox.fillRect(0,0,w,h);x.drawImage(overlay,0,0,c.width,c.height);}if(picking)marks(c,to,w,h);const rc=$('#reference-source');if(reference){fit(rc,reference);if(picking)marks(rc,from,reference.width,reference.height);}else{rc.width=640;rc.height=360;rc.getContext('2d').clearRect(0,0,640,360);}$('#reference-point-status').textContent=to.length===3?'Đã có ba cặp điểm. Chọn Tô vùng để ghép.':`Đã có ${to.length}/3 cặp. ${from.length===to.length?'Chọn điểm trên ảnh tham chiếu trước.':'Chọn điểm tương ứng trên ảnh gốc.'}`;}
  function invalidate(){result=null;$('[data-modal-button="1"]').disabled=true;draw();}
  function updateMode(){$('#reference-source-wrap').hidden=mode!=='reference';$('#reference-color-wrap').hidden=mode!=='color';for(const b of document.querySelectorAll('[data-precision-mode]'))b.classList.toggle('active',b.dataset.precisionMode===mode);$('#reference-description').textContent=mode==='reference'?'Lấy chi tiết từ bản scan khác hoặc ảnh cùng cảnh. Chọn ba cặp điểm căn chỉnh; chỉ ghép pixel tham chiếu vào vùng tô.':'Chọn màu đã biết rồi tô vùng. Thay sắc độ a/b trong Lab, giữ độ sáng L* của nguồn; màu ngoài gamut có thể bị giới hạn.';picking=false;invalidate();}
  async function loadReference(file){try{const read=await api.readImageFile(file),im=await api.assets.load(read.source);if(!mounted)return;const s=1;reference=canvas(Math.round(im.width*s),Math.round(im.height*s));reference.getContext('2d').drawImage(im,0,0,reference.width,reference.height);referenceName=file.name.slice(0,200);from=[];to=[];picking=true;$('#reference-source-label').textContent=referenceName;invalidate();note('Chọn ba cặp điểm: ảnh tham chiếu trước, ảnh gốc sau.');}catch(e){note(e.message);}}
  function preview(){try{const m=readMask(mask),strength=Number($('#reference-strength').value),feather=Number($('#reference-feather').value);if(!m.some(v=>v>.01))throw Error('Tô vùng cần phục hồi hoặc chọn vùng trên canvas trước.');if(mode==='reference'){if(!reference)throw Error('Chọn ảnh tham chiếu trước.');const matrix=affineFromPairs(from,to),rr=reference.getContext('2d').getImageData(0,0,reference.width,reference.height).data,generated=referencePatch(raw,w,h,rr,reference.width,reference.height,matrix,m,{strength:strength/100,feather});result=generated.data;record={version:1,operation:'reference-patch',sourceName:referenceName,matrix,points:{source:from.map(p=>({...p})),target:to.map(p=>({...p}))},strength,feather,processingSize:[w,h]};note(`Đã ghép ${generated.replaced.toLocaleString('vi-VN')} pixel tham chiếu. Kiểm tra đường nối và độ khớp; đây không phải AI tái dựng.`);}else{const color=$('#reference-color').value;result=guidedColor(raw,w,h,featherMask(m,w,h,feather),color,strength/100);record={version:1,operation:'guided-color',color,strength,feather,processingSize:[w,h]};note('Đã tạo bản màu theo màu bạn chọn. Kiểm tra vùng tô và so sánh trước/sau.');}picking=false;$('[data-modal-button="1"]').disabled=false;draw();}catch(e){note(e.message);}}
  function apply(){if(!result)return;if(JSON.stringify(api.doc())!==signature){note('Tài liệu đã đổi. Mở lại để tránh áp dụng nhầm.');return;}if(doc.layers.length>=150){note('Đã đạt giới hạn 150 layer.');return;}const out=canvas(w,h),x=out.getContext('2d'),im=x.createImageData(w,h);im.data.set(result);x.putImageData(im,0,0);const uri=out.toDataURL();api.assets.set(uri,out);const l=createLayer('image',{name:mode==='reference'?'Phục hồi · ảnh tham chiếu':'Màu · chỉ dẫn thủ công',source:uri,width:doc.width,height:doc.height,assistance:record});for(const a of doc.layers)if(!a.parentId)a.visible=false;doc.layers.push(l);doc.activeId=l.id;doc.selectedIds=[l.id];mounted=false;api.closeModal();api.commit(l.name);api.toast('Đã áp dụng layer riêng; các layer nguồn được giữ.');}
  api.showModal('Phục hồi có tham chiếu','Chi tiết từ tư liệu · màu do bạn kiểm soát',`<div class="precision-layout"><div><div class="reference-pair"><div><span class="reference-label">ẢNH GỐC / KẾT QUẢ</span><div class="gen-preview-wrap"><canvas id="reference-target" aria-label="Ảnh gốc: tô vùng hoặc chọn điểm đích"></canvas></div></div><div id="reference-source-wrap"><span class="reference-label" id="reference-source-label">ẢNH THAM CHIẾU</span><div class="gen-preview-wrap reference-empty"><canvas id="reference-source" aria-label="Ảnh tham chiếu: chọn điểm tương ứng"></canvas></div><input type="file" id="reference-file" accept="image/png,image/jpeg,image/webp" hidden><button class="button" id="reference-load">Chọn ảnh tham chiếu</button><p id="reference-point-status" class="gen-size-note"></p><div class="studio-button-grid"><button class="button" id="reference-points">Chọn / sửa 3 cặp điểm</button><button class="button" id="reference-same-frame">Căn theo cùng khung</button></div></div></div><div class="lab-compare"><span>Gốc</span><input id="reference-split" type="range" min="0" max="100" value="50" aria-label="So sánh kết quả tham chiếu"><span>Kết quả</span></div><p id="reference-status" class="advanced-status" role="status">Tô vùng cần sửa; các layer gốc được giữ bên dưới.</p></div><div class="precision-controls"><div class="lab-tabs"><button data-precision-mode="reference">Ghép tham chiếu</button><button data-precision-mode="color">Màu chỉ dẫn</button></div><p class="lab-explanation" id="reference-description"></p><div id="reference-color-wrap"><label class="modal-field">Màu đã biết / mong muốn<input type="color" id="reference-color" value="${esc(api.foreground?.()||'#bd886d')}" aria-label="Màu chỉ dẫn"></label><p class="gen-size-note">Có thể lấy màu bằng Eyedropper trước khi mở công cụ. Bản này không xác minh màu lịch sử.</p></div><div class="gen-brushes"><button class="button active" data-reference-brush="add">Tô vùng</button><button class="button" data-reference-brush="subtract">Trừ vùng</button><button class="button" id="reference-undo">Lùi nét</button><button class="button" id="reference-clear">Xóa vùng</button></div><label class="lab-slider">Cỡ cọ<input id="reference-brush" type="range" min="1" max="15" value="3.5" step=".5" aria-label="Cỡ cọ tham chiếu"></label><label class="lab-slider">Làm mềm mép vào trong<input id="reference-feather" type="range" min="0" max="40" value="4" aria-label="Làm mềm mép tham chiếu"></label><label class="lab-slider">Cường độ<output id="reference-amount">100%</output><input id="reference-strength" type="range" min="1" max="100" value="100" aria-label="Cường độ phục hồi tham chiếu"></label><button class="button primary" id="reference-preview">Tạo bản xem trước</button><p class="precision-note">Ảnh tham chiếu cần khớp cảnh, góc và thời điểm phù hợp. Căn affine không sửa phối cảnh hoặc khuôn mặt khác góc. Đầu ra giữ số pixel gốc theo khả năng bộ nhớ; nguồn được giữ riêng.</p></div></div>`,[{label:'Hủy',run:()=>api.closeModal(true)},{label:'Áp dụng layer riêng',primary:true,run:apply}],()=>{
   $('[data-modal-button="1"]').disabled=true;for(const b of document.querySelectorAll('[data-precision-mode]'))b.onclick=()=>{mode=b.dataset.precisionMode;updateMode();};$('#reference-load').onclick=()=>$('#reference-file').click();$('#reference-file').onchange=e=>{if(e.target.files?.[0])loadReference(e.target.files[0]);};$('#reference-preview').onclick=preview;$('#reference-split').oninput=e=>{split=Number(e.target.value);draw();};
   $('#reference-points').onclick=()=>{if(!reference){note('Chọn ảnh tham chiếu trước.');return;}from=[];to=[];picking=true;invalidate();};$('#reference-same-frame').onclick=()=>{if(!reference){note('Chọn ảnh tham chiếu trước.');return;}from=[{x:0,y:0},{x:reference.width-1,y:0},{x:0,y:reference.height-1}];to=[{x:0,y:0},{x:w-1,y:0},{x:0,y:h-1}];picking=false;invalidate();note('Đã căn theo khung; chỉ dùng khi hai ảnh có cùng bố cục.');};
   for(const b of document.querySelectorAll('[data-reference-brush]'))b.onclick=()=>{brush=b.dataset.referenceBrush;picking=false;document.querySelectorAll('[data-reference-brush]').forEach(a=>a.classList.toggle('active',a===b));draw();};$('#reference-brush').oninput=e=>brushSize=Number(e.target.value)/100;for(const id of['reference-feather','reference-strength','reference-color'])$('#'+id).oninput=()=>{$('#reference-amount').textContent=$('#reference-strength').value+'%';invalidate();};
   const snapshot=()=>{undo.push(mask.toDataURL());if(undo.length>10)undo.shift();};$('#reference-clear').onclick=()=>{snapshot();mx.clearRect(0,0,w,h);invalidate();};$('#reference-undo').onclick=async()=>{if(!undo.length)return;const image=await api.assets.load(undo.pop());if(mounted){mx.clearRect(0,0,w,h);mx.drawImage(image,0,0);invalidate();}};
   const target=$('#reference-target'),ref=$('#reference-source'),position=(e,c,sw,sh)=>{const r=c.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*sw,y:(e.clientY-r.top)/r.height*sh};};
   function stamp(a,b){mx.save();mx.globalCompositeOperation=brush==='subtract'?'destination-out':'source-over';mx.lineCap=mx.lineJoin='round';mx.lineWidth=brushSize*Math.max(w,h);mx.strokeStyle=mx.fillStyle='#fff';mx.beginPath();mx.moveTo(a.x,a.y);mx.lineTo(b.x,b.y);mx.stroke();mx.beginPath();mx.arc(b.x,b.y,mx.lineWidth/2,0,Math.PI*2);mx.fill();mx.restore();}
   ref.onpointerdown=e=>{if(!reference||!picking||e.button!==0)return;if(from.length!==to.length||from.length>=3){note('Chọn điểm tương ứng trên ảnh gốc hoặc bắt đầu lại.');return;}from.push(position(e,ref,reference.width,reference.height));invalidate();};target.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();if(picking){if(from.length<=to.length){note('Chọn điểm trên ảnh tham chiếu trước.');return;}to.push(position(e,target,w,h));if(to.length===3)picking=false;invalidate();return;}snapshot();target.setPointerCapture(e.pointerId);drawing=position(e,target,w,h);stamp(drawing,drawing);invalidate();};target.onpointermove=e=>{if(!drawing)return;const next=position(e,target,w,h);stamp(drawing,next);drawing=next;invalidate();};target.onpointerup=target.onpointercancel=()=>drawing=null;updateMode();
  },()=>{mounted=false;});
 }
 return{openSkin,openReference,cancel};
}
